                _reduceReturnValues(values) {
                    const { ReturnColumns } = this.outputData;
                    if (ReturnColumns && ReturnColumns.length) {
                        // 07.03.2019 - TFeik
                        // Pokud krok umožňuje zvolit funkci "AutoSelectLastValue",
                        // pak jej přidám do požadovaných sloupců a načtu hodnotu z formuláře.
                        if (this.outputData.AutoSelectLastValue != void 0) {
                            if (ReturnColumns.findIndex(c => c === "AutoSelectLastValue") === -1) {
                                ReturnColumns.push("AutoSelectLastValue");
                            }
                            if (this.table) {
                                values.AutoSelectLastValue = this.table
                                    .findForms("Choose1ofNAutoSelectLastValueForm")
                                    .findFields("autoSelectLastValue")
                                    .gfield("getValue");
                            }
                        }
                        return ReturnColumns.reduce((obj, column) => {
                            obj[column] = values[column];
                            return obj;
                        }, {});
                    }
                    return values;
                }
