                $dlg.on("close", (ev, profile) => {
                    if (!profile)
                        return;
                    this._favsPB = new Gordic.Utils.Menu.GMenuProfileBuilder(profile);
                    profile = this._favsPB.buildProfile();
                    this._saveFavsProfile(this.options.userSettings, profile);
                    this._favsProfiled = this._getFavsProfiled(this._favsPB, this._menuProfiled);
                    this._createFavorites(this._favsProfiled);
                    this._menuRebuildRequired = true;
                });
